-- Owner-reviewed draft wording for University, Banking, Insurance (types stay closed; choices stay draft).
-- label = partner-facing label, client_label = founder-facing label.
UPDATE public.service_catalog c SET label = v.label, client_label = v.client_label, description = v.description, updated_at = now()
FROM (VALUES
('uni-incubator-or-accelerator-referrals','Incubator or accelerator referrals','Campus incubator or accelerator referral','If the institution runs an incubator or accelerator, its program office may refer founders. The program decides admission.'),
('uni-entrepreneurship-course-guest-sessions','Entrepreneurship course guest sessions','Guest speaking in entrepreneurship courses','Faculty may invite business owners to speak in courses, at the course''s discretion.'),
('uni-student-venture-support','Student venture support','Student venture support','Guidance the institution offers student-led ventures, where it runs such a program.'),
('uni-alumni-founder-support','Alumni founder support','Alumni founder resources','Connects alumni founders with campus resources the institution currently offers alumni.'),
('uni-internships-and-co-ops','Internships and co-ops','Internship and co-op recruiting','Businesses can ask to post internship or co-op roles through the career office, under its policies.'),
('uni-capstone-and-class-projects','Capstone and class projects','Capstone and class project requests','Businesses can propose a project. Faculty decide whether it fits a course.'),
('uni-student-consulting-projects','Student consulting projects','Student consulting project requests','Businesses can propose a problem for a faculty-guided student team, where that program exists.'),
('uni-career-fair-participation','Career fair participation','Career fair participation','Businesses can ask to recruit at the institution''s career fairs, under its registration rules.'),
('uni-international-student-entrepreneurship-events','International student entrepreneurship events','International student entrepreneurship events','General events on starting a venture, hosted by the institution for its international students.'),
('uni-referrals-to-campus-international-offices','Referrals to campus international offices','Referral to the campus international office','Points the institution''s own students and scholars to their campus international office.'),
('uni-opt-and-cpt-awareness-sessions','University-led OPT/CPT information sessions','University-led OPT/CPT information sessions','General group sessions led by the university and coordinated with its international student office. They share general information only, not individual immigration advice. Students should ask their designated school official or an immigration attorney about their own situation.'),
('uni-technology-transfer-contacts','Technology transfer contacts','Technology transfer office contact','Where there is a technology transfer office, founders can ask about licensing or working together. That office sets the terms.'),
('uni-faculty-startup-support','Faculty startup support','Faculty startup support','Support for faculty forming companies, where the institution offers it.'),
('uni-research-partnership-inquiries','Research partnership inquiries','Research partnership inquiry','Businesses can ask about sponsored research or joint projects. The institution decides whether to go ahead.'),
('uni-workshops-and-speaker-events','Workshops and speaker events','Workshops and speaker events','The program may co-host workshops or speaker events for founders when it chooses.'),
('uni-pitch-competitions','Pitch competitions','Pitch competition participation','Founders or judges can ask about the institution''s pitch competitions. Its own eligibility rules apply.'),
('uni-small-business-outreach-programs','Small-business outreach programs','Small-business outreach programs','Programs the institution currently runs for local small businesses.'),
('bank-business-checking-and-savings','Business checking and savings','Business checking and savings inquiries','The bank accepts inquiries about business deposit accounts. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-merchant-services','Merchant services','Merchant services inquiries','The bank accepts inquiries about card processing and payment acceptance. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-treasury-and-cash-management','Treasury and cash management','Treasury and cash management inquiries','The bank accepts inquiries about treasury and cash management tools. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-foreign-owned-or-non-resident-business-account-i','Foreign-owned or non-resident business account inquiries','Inquiries about accounts for foreign-owned or non-resident businesses','The bank accepts inquiries from founders who live abroad or whose company has a foreign owner. This does not mean an account can be opened. The bank applies its own identity, residency, and compliance requirements. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-sba-loan-inquiries','SBA loan inquiries','SBA loan inquiries','The bank accepts inquiries about SBA-backed lending. This does not indicate eligibility or approval. SBA and bank requirements apply. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-lines-of-credit','Lines of credit','Line of credit inquiries','The bank accepts inquiries about lines of credit. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-equipment-financing','Equipment financing','Equipment financing inquiries','The bank accepts inquiries about equipment financing. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-commercial-real-estate-lending','Commercial real estate lending','Commercial real estate lending inquiries','The bank accepts inquiries about loans for business property. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-business-credit-cards','Business credit cards','Business credit card inquiries','The bank accepts inquiries about business credit cards. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-startup-banking-packages','Startup banking inquiries','Startup banking inquiries','The bank accepts banking inquiries from early-stage companies. This does not mean a package is available to every startup. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-venture-backed-company-banking','Venture-backed company banking inquiries','Venture-backed company banking inquiries','The bank accepts inquiries from companies raising or holding venture capital. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-banking-for-newly-formed-entities','Newly formed company banking inquiries','Newly formed company banking inquiries','The bank accepts inquiries from recently formed companies. Opening an account depends on its documentation requirements. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-international-wires-and-fx','International wires and FX','International wires and FX inquiries','The bank accepts inquiries about cross-border payments and currency exchange. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('bank-trade-finance-inquiries','Trade finance inquiries','Trade finance inquiries','The bank accepts inquiries about letters of credit and import or export financing. An inquiry is not an application. The bank alone decides availability, eligibility, and terms.'),
('ins-general-liability','General liability','General liability inquiry','The broker handles inquiries about coverage for third-party injury and property damage claims. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-business-owner-s-policy','Business owner''s policy','Business owner''s policy inquiry','The broker handles inquiries about bundled property and liability policies for small businesses. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-commercial-property','Commercial property','Commercial property inquiry','The broker handles inquiries about coverage for business buildings and contents. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-commercial-auto','Commercial auto','Commercial auto inquiry','The broker handles inquiries about coverage for business vehicles. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-professional-liability-e-o','Professional liability / E&O','Professional liability / E&O inquiry','The broker handles inquiries about coverage for claims of errors in professional services. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-directors-and-officers','Directors and officers','Directors and officers inquiry','The broker handles inquiries about coverage related to leadership decisions. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-employment-practices-liability','Employment practices liability','Employment practices liability inquiry','The broker handles inquiries about coverage for employee-related claims. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-fiduciary-liability','Fiduciary liability','Fiduciary liability inquiry','The broker handles inquiries about coverage related to managing benefit plans. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-cyber-liability','Cyber liability','Cyber liability inquiry','The broker handles inquiries about coverage for data breaches and cyber incidents. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-technology-e-o','Technology E&O','Technology E&O inquiry','The broker handles inquiries about errors and omissions coverage for technology companies. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-workers-compensation','Workers'' compensation','Workers'' compensation inquiry','The broker handles inquiries about coverage for employee workplace injuries. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-group-health','Group health','Group health inquiry','The broker handles inquiries about employee health plans. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-group-dental-and-vision','Group dental and vision','Group dental and vision inquiry','The broker handles inquiries about employee dental and vision plans. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-group-life-and-disability','Group life and disability','Group life and disability inquiry','The broker handles inquiries about employee life and disability plans. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-product-liability','Product liability','Product liability inquiry','The broker handles inquiries about coverage for claims arising from products a business sells. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-surety-bonds','Surety bonds','Surety bond inquiry','The broker handles inquiries about bonds required by contracts or licenses. Issuing a bond depends on the surety''s own review. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-inland-marine-and-equipment','Inland marine and equipment','Inland marine and equipment inquiry','The broker handles inquiries about coverage for equipment and goods in transit. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.'),
('ins-event-and-hospitality-coverage','Event and hospitality coverage inquiries','Event and hospitality coverage inquiry','The broker handles inquiries about coverage for events, restaurants, and hospitality businesses. Whether a given event is covered depends on the policy an insurer issues. An inquiry does not mean a policy is available or that a particular loss or event is covered. Insurers set terms.')
) AS v(id, label, client_label, description)
WHERE c.id = v.id;

INSERT INTO public.service_catalog_changes (service_id, change_type, new_label, catalog_version)
SELECT id, 'updated', label, 2 FROM public.service_catalog WHERE partner_type IN ('university','banking','insurance');